import React from 'react';

import { omitTransientProps } from 'utils/emotion';

import { StyledTabsContent } from '../Tabs.styles';
import type { TabsContentProps } from '../Tabs.types';

export const TabsContent = React.forwardRef<
  React.ElementRef<typeof StyledTabsContent>,
  TabsContentProps
>(({ className, ...props }, forwardedRef) => (
  <StyledTabsContent
    {...omitTransientProps(props)}
    ref={forwardedRef}
    className={className}
  />
));

TabsContent.displayName = 'Tabs.Content';
